#!/bin/sh
# Output parity of the Jinja template sets: each project generated by the TypeScript generator
# with legacy/liquid/<set> and by the Rust scaffold-gen with templates/<set> over the context
# of the TypeScript generator (scripts/dump-context.ts), diffed (records too).
# Usage: scripts/dev/compare_outputs.sh [-w workdir] set [project file]...   (from the repository root)
set -u
work=${TMPDIR:-/tmp}/scaffold-outputs
if [ "${1-}" = -w ]; then work=$2; shift 2; fi
set_=$1
shift
gen=${SCAFFOLD_GEN:-rust/target/release/scaffold-gen}
[ $# -gt 0 ] || set -- examples/robot.scaffold.yaml examples/rover.scaffold.yaml examples/station.scaffold.yaml \
	examples/idl/filling_cell.scaffold.yaml tests/fixtures/plant.scaffold.yaml tests/fixtures/relay.scaffold.yaml
fail=0
for f in "$@"; do
	name=$(basename "$f" .scaffold.yaml)
	a=$work/$set_/$name.ts
	b=$work/$set_/$name.j2
	rm -rf "$a" "$b"; mkdir -p "$work/$set_"
	npx tsx scripts/generate.ts "$f" -t "$set_" -o "$a" -f >/dev/null 2>"$a.err" || { echo "TS failed: $f"; cat "$a.err"; }
	npx tsx scripts/dump-context.ts "$f" >"$work/$set_/$name.ctx.json"
	"$gen" --context "$work/$set_/$name.ctx.json" -t "$set_" -o "$b" -f >/dev/null 2>"$b.err" ||
		{ echo "rust failed: $f"; head -5 "$b.err"; fail=1; continue; }
	if diff -r "$a" "$b" >"$work/$set_/$name.diff" 2>&1; then
		echo "ok $set_ $name"
	else
		echo "DIFF $set_ $name: $(grep -c '^[<>]' "$work/$set_/$name.diff") lines, $work/$set_/$name.diff"
		fail=1
	fi
done
exit $fail
